import type { Step } from '@aitomate/schema';

export const MANUAL_STEP_ACTIONS = ['click', 'fill', 'navigate', 'wait', 'assert'] as const;
export type ManualStepAction = (typeof MANUAL_STEP_ACTIONS)[number];

/**
 * Build a blank step of the given action type for manual insertion (T2.11).
 * `id` is generated by the caller (crypto.randomUUID()) — not here — so this
 * stays a pure function callers can test without stubbing global crypto.
 */
export function buildManualStep(action: ManualStepAction, id: string): Step {
  switch (action) {
    case 'navigate':
      return { id, action: 'navigate', url: '' };
    case 'click':
      return { id, action: 'click', selector: { strategy: 'css', value: '' } };
    case 'fill':
      return {
        id,
        action: 'fill',
        selector: { strategy: 'css', value: '' },
        resolver: { type: 'static', value: '' },
      };
    case 'wait':
      return { id, action: 'wait', durationMs: 1000 };
    case 'assert':
      return {
        id,
        action: 'assert',
        assertion: 'elementVisible',
        selector: { strategy: 'css', value: '' },
      };
  }
}
